def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_op = history[-1]

    opp_d = 0
    for _, b in history:
        if b == 'D':
            opp_d += 1

    unpunished = False
    for i in range(n - 1):
        if (history[i][0] == 'D' and history[i][1] == 'C' and
            history[i + 1][0] == 'C' and history[i + 1][1] == 'C'):
            unpunished = True
            break

    recent_d = 0
    for i in range(max(0, n - 6), n):
        if history[i][1] == 'D':
            recent_d += 1

    tail = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            tail += 1
        else:
            break

    if opp_d == 0 and unpunished:
        return 'D'

    if opp_d == 0:
        if last_my == 'D':
            return 'C'
        if n >= 20 and last_op == 'C':
            return 'D'
        return 'C'

    if last_op == 'D':
        if opp_d * 4 <= n and tail <= 2:
            if (last_my == 'D' or
                (n >= 2 and history[-2][0] == 'D') or
                (n >= 3 and history[-3][0] == 'D')):
                return 'C'
        if tail >= 3 or recent_d >= 3 or opp_d * 2 > n:
            return 'D'
        return 'D'

    if recent_d >= 3 or opp_d * 2 > n:
        return 'D'

    return 'C'
